203	/* Exposed to Tailwind so the product can be written as `bg-surface`,
204	   `text-text-2`, `border-border-mid`, `rounded-lg` etc. rather than as
205	   arbitrary-value brackets on every element. This is the whole reason the
206	   design system holds together across pages written by different hands. */
207	@theme inline {
208	  --color-background: var(--background);
209	  --color-foreground: var(--foreground);
210	  --font-sans: var(--font-geist-sans);
211	  --font-mono: var(--font-geist-mono);
212	
213	  --color-canvas: var(--surface-canvas);
214	  --color-surface: var(--surface);
215	  --color-surface-2: var(--surface-2);
216	  --color-surface-3: var(--surface-3);
217	  --color-inset: var(--surface-inset);
218	
219	  --color-hair: var(--border-soft);
220	  --color-line-mid: var(--border-mid);
221	  --color-line-strong: var(--border-strong);
222	
223	  --color-ink: var(--text-1);
224	  --color-ink-2: var(--text-2);
225	  --color-ink-3: var(--text-3);
226	  --color-ink-inv: var(--text-inv);
227	
228	  --color-brand: var(--brand);
229	  --color-brand-hover: var(--brand-hover);
230	  --color-brand-tint: var(--brand-tint);
231	  --color-brand-tint-2: var(--brand-tint-2);
232	  --color-brand-ink: var(--brand-ink);
233	
234	  --color-ok: var(--ok);
235	  --color-ok-tint: var(--ok-tint);
236	  --color-warn: var(--warn);
237	  --color-warn-tint: var(--warn-tint);
238	  --color-danger: var(--danger);
239	  --color-danger-tint: var(--danger-tint);
240	  --color-info: var(--info);
241	  --color-info-tint: var(--info-tint);
242	
243	  --radius-xs: var(--r-xs);
244	  --radius-sm: var(--r-sm);
245	  --radius-md: var(--r-md);
246	  --radius-lg: var(--r-lg);
247	  --radius-xl: var(--r-xl);
248	  --radius-2xl: var(--r-2xl);
249	
250	  --shadow-e1: var(--e1);
251	  --shadow-e2: var(--e2);
252	  --shadow-e3: var(--e3);
253	}
