688	   32px+ the default spacing reads loose); the label size gets positive
689	   tracking and uppercase, which is the only place caps are used. */
690	.k-display {
691	  font-size: clamp(1.75rem, 1.2rem + 1.6vw, 2.35rem);
692	  line-height: 1.1;
693	  letter-spacing: -0.028em;
694	  font-weight: 600;
695	  text-wrap: balance;
696	}
697	.k-h1 {
698	  font-size: 1.5rem;
