715	  color: var(--text-3);
716	}
717	/* Anywhere digits stack in a column — usage, credits, invoices, versions. */
718	.k-num {
719	  font-variant-numeric: tabular-nums;
720	  font-feature-settings: "tnum" 1;
721	}
722	
723	/* Any wide child (table, code, diagram) scrolls inside its own box so the
724	   page body never scrolls sideways. */
725	.k-scroll-x {
726	  overflow-x: auto;
727	  overscroll-behavior-x: contain;
728	}
