739	/* ── AI progress: the three states a step can be in ──
740	   Reused by the build overlay, the chat progress list and the preview
741	   loading treatment, so all three read as the same object. */
742	@keyframes k-step-pulse {
743	  0%,
744	  100% {
745	    opacity: 0.45;
746	    transform: scale(0.88);
747	  }
748	  50% {
749	    opacity: 1;
750	    transform: scale(1);
751	  }
752	}
753	.k-step-active {
754	  animation: k-step-pulse 1.4s var(--ease-io) infinite;
755	}
756	
757	@keyframes k-step-in {
758	  from {
759	    opacity: 0;
760	    transform: translateY(4px);
761	  }
762	  to {
763	    opacity: 1;
764	    transform: translateY(0);
765	  }
766	}
767	.k-step-in {
768	  animation: k-step-in 0.32s var(--ease) both;
769	}
770	
771	/* The travelling sheen along an in-progress bar. Position, not a moving
772	   child, so there is nothing to clip. */
773	@keyframes k-indeterminate {
774	  from {
775	    background-position: 200% 0;
776	  }
777	  to {
778	    background-position: -200% 0;
779	  }
780	}
781	.k-indeterminate {
782	  background-image: linear-gradient(
783	    90deg,
784	    var(--brand-tint) 0%,
785	    var(--brand) 40%,
786	    var(--brand) 60%,
787	    var(--brand-tint) 100%
788	  );
789	  background-size: 200% 100%;
790	  animation: k-indeterminate 1.6s linear infinite;
791	}
792	
793	/* Preview while the AI is applying a change. Deliberately mild: the customer
794	   must still recognise their own site underneath, otherwise it reads as the
795	   site having been replaced rather than edited. */
796	.k-preview-busy {
797	  filter: blur(2.5px) saturate(0.82);
798	  transform: scale(1.008);
