814	  from {
815	    opacity: 0;
816	    transform: translateY(8px);
817	  }
818	  to {
819	    opacity: 1;
820	    transform: translateY(0);
821	  }
822	}
823	.k-msg-in {
824	  animation: k-msg-in 0.28s var(--ease) both;
825	}
826	
827	/* Ambient brand wash for hero panels inside the product (dashboard welcome,
828	   create-website prompt). Softer than the marketing .aura and NOT fixed —
829	   it belongs to its panel and scrolls with it. */
830	.k-wash {
831	  position: absolute;
832	  inset: 0;
833	  pointer-events: none;
834	  overflow: hidden;
835	  border-radius: inherit;
836	}
837	.k-wash::before,
838	.k-wash::after {
839	  content: "";
840	  position: absolute;
841	  border-radius: 50%;
842	  filter: blur(72px);
843	}
844	.k-wash::before {
845	  width: 46%;
846	  aspect-ratio: 1;
847	  left: -6%;
848	  top: -42%;
849	  background: radial-gradient(closest-side, var(--glow), transparent);
850	}
851	.k-wash::after {
852	  width: 40%;
853	  aspect-ratio: 1;
854	  right: -4%;
855	  bottom: -50%;
856	  background: radial-gradient(closest-side, var(--glow-2), transparent);
857	}
858	
859	/* Sidebar collapse. The width lives on the shell as a custom property so the
860	   sidebar, the mobile drawer and the main column all animate off one value
861	   and cannot disagree mid-transition. */
862	.k-shell {
863	  --shell-sidebar: var(--sidebar-w);
864	}
