25	const SIZE: Record<ButtonSize, string> = {
26	  xs: "h-7 gap-1.5 px-2.5 text-xs rounded-sm",
27	  sm: "h-8 gap-1.5 px-3 text-[0.8125rem] rounded-md",
28	  md: "h-9.5 gap-2 px-4 text-sm rounded-md",
29	  lg: "h-11.5 gap-2 px-5 text-[0.9375rem] rounded-lg",
