32	export function buttonClass({
33	  variant = "secondary",
34	  size = "md",
35	  block = false,
36	  className = "",
37	}: {
38	  variant?: ButtonVariant;
39	  size?: ButtonSize;
40	  block?: boolean;
41	  className?: string;
