188	/**
189	 * Delete. Irreversible — there is no soft-delete column and no undo.
190	 *
191	 * Cascade behaviour below was verified against the live Postgres FK catalog
192	 * (pg_constraint.confdeltype), not just read off schema.prisma:
193	 *   ProjectFile -> Project  ON DELETE CASCADE
194	 *   Message     -> Project  ON DELETE CASCADE
195	 *   Build       -> Project  ON DELETE CASCADE
196	 *   CreditLedger -> Build   ON DELETE SET NULL
197	 *
198	 * Two consequences worth stating explicitly:
199	 *
200	 * 1. THIS TAKES A PUBLISHED SITE OFFLINE. The cascade removes the
201	 *    `published: true` rows the public site route serves, and the Project row
202	 *    it resolves the slug by — so `<slug>.kodely.site` 404s. Deleting is the
203	 *    only way to withdraw a published site, and it must actually withdraw it.
204	 *    (Note: that route sends `Cache-Control: public, max-age=60`, so an already
205	 *    cached response can survive up to a minute at the edge/browser.)
206	 *
207	 * 2. THE CREDIT LEDGER SURVIVES. Builds cascade away, but CreditLedger rows
208	 *    referencing them are SET NULL, not deleted — the rows remain with
209	 *    `buildId: null`. getBalance() reads `balanceAfter` off the newest ledger
210	 *    row (lib/credits.ts), so a delete cannot alter, refund, or erase spend.
211	 *    That is the correct behaviour for an auditable ledger: deleting the
212	 *    artifact does not un-charge the work that produced it.
213	 */
214	export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
215	  const user = await requireUser().catch(() => null);
216	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
217	  const { id } = await params;
218	
219	  // Read before deleting so the event can record whether a LIVE site just went
220	  // offline — afterwards there is nothing left to ask. Ownership is still scoped
221	  // in the delete itself, so this read is for telemetry, not authorization.
222	  const existing = await db.project.findFirst({
223	    where: { id, userId: user.id },
224	    select: { publishedAt: true, createdAt: true },
225	  });
226	
227	  // Ownership scoped in the same query as the id — see the note on PATCH.
228	  const { count } = await db.project.deleteMany({ where: { id, userId: user.id } });
229	  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });
230	
231	  track(EVENTS.projectDeleted, {
232	    userId: user.id,
233	    props: {
234	      projectId: id,
235	      wasPublished: Boolean(existing?.publishedAt),
236	      ageHours: existing
237	        ? Math.round((Date.now() - existing.createdAt.getTime()) / 3_600_000)
238	        : null,
239	    },
240	  });
241	
242	  return Response.json({ ok: true });
243	}
