46	// Strip CR/LF before any user-supplied value reaches a mail HEADER. Without
47	// this a visitor could put "\r\nBcc: victim@example.com" in the name field
48	// and turn this form into an open relay (classic SMTP header injection).
49	// Body content doesn't need this — only headers.
50	function headerSafe(value: string, max = 200): string {
51	  return value.replace(/[\r\n]+/g, " ").trim().slice(0, max);
52	}
