69	export async function sendContactEmail(input: {
70	  name: string;
71	  email: string;
72	  message: string;
73	}): Promise<void> {
74	  const name = headerSafe(input.name, 120);
75	  const email = headerSafe(input.email, 200);
76	  const message = input.message.slice(0, 5000);
77	
78	  await transporter().sendMail({
79	    from: FROM,
80	    to: CONTACT_TO,
81	    // Reply-To carries the visitor's address, NOT From. Sending as the
82	    // visitor's own domain would fail that domain's SPF/DMARC and get the
83	    // mail junked or rejected — but replying in a mail client still goes
84	    // straight to them, which is the behaviour actually wanted here.
85	    replyTo: `${name} <${email}>`,
86	    subject: `Kodely contact — ${name || email}`,
87	    text: `From: ${name} <${email}>\n\n${message}\n`,
88	  });
89	}
