89	export type DiscordConfig = { clientId: string; clientSecret: string; guildId: string };
90	
91	/** Null unless ALL THREE Discord values are present — a half-configured OAuth client fails at Discord, not here. */
92	export function discordConfig(): DiscordConfig | null {
93	  const clientId = process.env.KODELY_DISCORD_CLIENT_ID;
94	  const clientSecret = process.env.KODELY_DISCORD_CLIENT_SECRET;
95	  const guildId = process.env.KODELY_DISCORD_GUILD_ID;
96	  if (!clientId || !clientSecret || !guildId) return null;
97	  return { clientId, clientSecret, guildId };
98	}
