128	// ── Identity hashing ──────────────────────────────────────────────────────
129	
130	/**
131	 * Stable, secret-keyed fingerprint of an external account. Namespaced by
132	 * platform so the same string on two platforms is two identities, and
133	 * truncated to 96 bits — far past any collision concern at this scale, and
134	 * short enough to keep `reason` readable in an admin query.
135	 *
136	 * Returns null when unkeyed; callers must treat that as "cannot grant".
137	 */
138	export function identityHash(platform: Platform, externalId: string): string | null {
139	  const secret = identitySecret();
140	  if (secret === null) return null;
141	  return createHmac("sha256", secret)
142	    .update(`${platform}:${externalId}`)
143	    .digest("hex")
144	    .slice(0, 24);
145	}
