212	/** The pending (unverified) claim for this user+platform, if one exists. */
213	export async function pendingClaim(userId: string, platform: Platform) {
214	  return db.creditLedger.findFirst({
215	    where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:pending:` } },
216	    orderBy: { createdAt: "desc" },
217	    select: { reason: true, createdAt: true },
218	  });
219	}
