19	// server the user is in; we have no business seeing that, and asking for it
20	// would make the consent screen alarming for no gain.
21	//
22	// Nothing here is trusted from the browser. The user identity comes from the
23	// session cookie, the guild membership comes from Discord's API, and the two
24	// are tied together by a state cookie that also pins WHICH Kodely user started
25	// the flow — so a callback replayed into a different session cannot land.
26	
27	const STATE_COOKIE = "kodely_discord_reward_state";
