29	export async function GET(req: Request) {
30	  const origin = originFromRequest(req);
31	  const user = await getCurrentUser();
32	  if (!user) return Response.redirect(`${origin}/login`, 302);
33	
34	  const config = discordConfig();
35	  // Unconfigured is not an error — the reward simply does not exist. The
36	  // settings page will not have shown a button; a hand-typed URL lands here.
37	  if (!config || identitySecret() === null) {
38	    console.error(
39	      "[rewards] Discord reward hit without full config (KODELY_DISCORD_CLIENT_ID / _SECRET / _GUILD_ID, KODELY_REWARDS_ID_SALT).",
40	    );
41	    return Response.redirect(`${origin}/settings?reward=unavailable`, 302);
42	  }
43	
44	  if (await hasClaimed(user.id, "discord")) {
45	    return Response.redirect(`${origin}/settings?reward=already`, 302);
46	  }
47	  if (accountTooNew(user.createdAt)) {
48	    return Response.redirect(`${origin}/settings?reward=too_new`, 302);
49	  }
50	
51	  // The state cookie carries the user id alongside the nonce. Both are
52	  // re-checked in the callback: the nonce proves the round trip started here,
53	  // the user id proves it started in THIS session.
54	  const nonce = randomBytes(24).toString("base64url");
55	  const state = `${nonce}.${user.id}`;
56	
57	  const authUrl = new URL("https://discord.com/oauth2/authorize");
58	  authUrl.searchParams.set("client_id", config.clientId);
59	  authUrl.searchParams.set("redirect_uri", `${origin}/api/rewards/discord/callback`);
60	  authUrl.searchParams.set("response_type", "code");
61	  authUrl.searchParams.set("scope", "identify guilds.members.read");
