              status={
                <Badge tone="ok" dot>
                  Active
                </Badge>
              }
            >
              {usesGoogle && usesPassword ? (
                <p>
                  Your account has both a Google sign-in and a Kodely password. Either one gets you
                  in, and both point at <span className="font-medium text-ink">{user.email}</span>.
                </p>
              ) : usesGoogle ? (
                <p>
                  You sign in with Google. Kodely stores your Google account id and your email
                  address — <span className="font-medium text-ink">{user.email}</span> — and never
                  had a password for you to lose.
                </p>
              ) : (
                <p>
                  You sign in with an email address and a password:{" "}
                  <span className="font-medium text-ink">{user.email}</span>. Signing in with Google
                  is also supported, on accounts that were created that way.
                </p>
              )}
              <p className="text-ink-3">
                Kodely asks Google for your email address and nothing else. There is no calendar,
                drive or contacts access to review.
              </p>
            </Row>

            <Row
              icon={<Mail className="size-4.5" aria-hidden />}
              title="Email from Kodely"
              status={
                mailReady ? (
                  <Badge tone="ok" dot>
                    Sending
                  </Badge>
                ) : (
                  <Badge tone="warn" dot>
                    Off right now
                  </Badge>
                )
              }
            >
              {mailReady ? (
                <>
                  <p>
                    Kodely emails <span className="font-medium text-ink">{user.email}</span> about
                    four things, and only these four: a welcome when you sign up, a warning when
                    your credits are running low, a notice when a build fails, and a confirmation
                    when a site goes live.
                  </p>
                  <p className="text-ink-3">
                    There are no notification settings, because there is nothing to choose between
                    — all four are about your own account and none of them are marketing.
                  </p>
                </>
              ) : (
                <p>
                  Email delivery is not configured on this deployment, so Kodely will not email you
                  at all — no welcome, no low-credit warning, no build-failure notice, no
                  publish confirmation. Nothing is queued for later either. Reach a person at{" "}
                  <a
                    href={`mailto:${CONTACT_TO}`}
                    className="k-focus rounded-sm font-medium text-brand underline underline-offset-2"
                  >
                    {CONTACT_TO}
                  </a>
                  .
                </p>
              )}
            </Row>

            <Row
              icon={<CreditCard className="size-4.5" aria-hidden />}
              title="Stripe"
              status={
                stripeReady ? (
                  <Badge tone="ok" dot>
                    Handling payments
                  </Badge>
                ) : (
                  <Badge tone="warn" dot>
                    Off right now
                  </Badge>
                )
              }
            >
              {stripeReady ? (
                <>
                  <p>
                    Card payments go to Stripe&apos;s own checkout. Kodely never sees or stores your
                    card, and there is no saved payment method here to manage.
                  </p>
                  <p className="text-ink-3">
                    Every purchase is a one-off credit pack. There is no subscription, so there is
                    nothing to cancel and no renewal date to watch.
                  </p>
                </>
              ) : (
                <p>
                  Card payments are not configured on this deployment, so credit packs cannot be
                  bought right now. Existing credits are unaffected.
                </p>
              )}
            </Row>

            <Row
              icon={<Inbox className="size-4.5" aria-hidden />}
              title="Forms on your published sites"
              status={
                publishedSites > 0 ? (
                  <Badge tone="ok" dot>
                    Receiving
                  </Badge>
                ) : (
                  <Badge tone="neutral">Ready when you publish</Badge>
                )
              }
            >
              <p>
                A contact form on a site you publish posts back to Kodely, not to a third-party form
                service. Submissions land in that site&apos;s inbox in the builder
                {submissions > 0 ? (
                  <>
                    {" "}
                    — <span className="k-num font-medium text-ink">{submissions}</span> so far
                    across your sites
                  </>
                ) : null}
                .
              </p>
              <p className="text-ink-3">
                {mailReady
                  ? "You also get an email for each one, capped at ten an hour per site so a burst of spam cannot flood your inbox. There is no forwarding to a CRM or a spreadsheet."
                  : "Email delivery is off on this deployment, so submissions are stored and readable in the builder but nothing is emailed to you."}
              </p>
            </Row>

            {discordConfigured ? (
              <Row
                icon={<MessagesSquare className="size-4.5" aria-hidden />}
                title="Discord"
                status={
                  discordClaimed ? (
                    <Badge tone="ok" dot>
                      Claimed
                    </Badge>
                  ) : (
                    <Badge tone="info" dot>
                      Available
                    </Badge>
                  )
                }
              >
                <p>
                  Joining the Discord and authorising once is worth a one-off{" "}
                  <span className="k-num font-medium text-ink">{REWARD_CREDITS}</span> credits.
                  Discord tells us whether you are actually in the server; that check is the whole
                  of the connection.
                </p>
                <p className="text-ink-3">
                  It is not an ongoing link. Kodely does not read your messages, does not post
                  anything, and does not keep talking to Discord afterwards.{" "}
                  <Link
                    href="/settings"
                    className="k-focus rounded-sm font-medium text-brand underline underline-offset-2"
                  >
                    {discordClaimed ? "See it in Settings" : "Claim it in Settings"}
                  </Link>
                  .
                </p>
              </Row>
            ) : null}
          </ul>
        </Card>
      </div>

      <Card>
        <CardHeader
          title="What Kodely does not connect to"
          description="Not hidden behind a plan, not in a private beta. These do not exist in the product."
        />
        <ul className="mt-4 grid gap-x-8 gap-y-3 text-sm leading-relaxed text-ink-2 sm:grid-cols-2">
          {[
            "An API or API keys for Kodely itself",
            "Webhooks for builds, publishes or form submissions",
            "Your own analytics — Google Analytics, Plausible, anything",
            "A CRM or a mailing list to send form submissions on to",
            "Zapier, Make, or any automation tool",
            "A CMS, so somebody else can edit the copy",
            "Taking payments or bookings on a site you built here",
            "Anything that would need a token or a secret stored for you",
          ].map((item) => (
            <li key={item} className="flex gap-2.5">
              <span aria-hidden className="mt-2 size-1.5 shrink-0 rounded-full bg-ink-3" />
              <span>{item}</span>
            </li>
          ))}
        </ul>
        <p className="mt-5 border-t border-hair pt-4 text-sm leading-relaxed text-ink-2">
          There is nowhere in Kodely to store a key or a token for you, and no route that calls out
          to a service on your behalf, so none of the above can be quietly half-working. If one of
          them is the thing standing between you and using Kodely properly,{" "}
          <Link
            href="/support"
            className="k-focus rounded-sm font-medium text-brand underline underline-offset-2"
          >
            say which one
          </Link>{" "}
          — that is the only signal that moves this list.
        </p>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Send } from "lucide-react";
import { Button, buttonClass } from "@/components/ui/Button";
import { Input, Select, Textarea } from "@/components/ui/Field";

export type SupportSite = {
  id: string;
  name: string;
  /** The real public address, computed server-side. Not a guess. */
  address: string;
  published: boolean;
};

/* The message body is capped below the endpoint's own 5000-character ceiling
   so that the site context prepended in `compose` can never be what pushes a
   perfectly reasonable message over the limit. */
const MESSAGE_MAX = 4000;

type Status = "idle" | "sending" | "sent";

function compose(input: {
  accountEmail: string;
  site: SupportSite | undefined;
  message: string;
}): string {
  const { accountEmail, site, message } = input;
  const lines = [`Kodely account: ${accountEmail}`];

  if (site) {
    lines.push(`Site: ${site.name}`);
    lines.push(`Address: ${site.address}${site.published ? "" : " (not published yet)"}`);
    lines.push(`Builder: ${window.location.origin}/projects/${site.id}`);
  } else {
    lines.push("Site: not about one specific site");
  }

  return `${lines.join("\n")}\n\n---\n\n${message}`;
}

export function ContactPanel({
  accountEmail,
  accountName,
  sites,
  contactEmail,
}: {
  accountEmail: string;
  accountName: string;
  sites: SupportSite[];
  contactEmail: string;
}) {
  const [name, setName] = useState(accountName);
  const [email, setEmail] = useState(accountEmail);
  const [siteId, setSiteId] = useState("");
  const [message, setMessage] = useState("");
  const [status, setStatus] = useState<Status>("idle");
  const [error, setError] = useState<string | null>(null);

  function submit(event: React.FormEvent) {
    event.preventDefault();
    if (status === "sending") return;
    setStatus("sending");
    setError(null);

    const body = JSON.stringify({
      name: name.trim(),
      email: email.trim(),
      message: compose({
        accountEmail,
        site: sites.find((s) => s.id === siteId),
        message: message.trim(),
      }),
    });

    void (async () => {
      try {
        const res = await fetch("/api/contact", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body,
        });
        // Every failure branch of /api/contact returns a sentence written for a
        // person — not configured, rate limited, rejected, SMTP down — so the
        // honest thing is to show it rather than replace it with our own guess.
        const data = (await res.json().catch(() => ({}))) as { error?: string };
        if (!res.ok) {
          setError(data.error ?? "That didn't send, and we don't know why.");
          setStatus("idle");
          return;
        }
        setStatus("sent");
        setMessage("");
      } catch {
        setError(`Couldn't reach Kodely at all. Email ${contactEmail} directly and it will land.`);
        setStatus("idle");
      }
    })();
  }

  if (status === "sent") {
    return (
      <div role="status" className="rounded-lg border border-ok/30 bg-ok-tint p-5">
        <p className="k-h2 text-ink">Sent</p>
        <p className="mt-2 text-sm leading-relaxed text-ink-2">
          It is in the inbox a person reads. The reply goes to{" "}
          <span className="font-medium text-ink">{email}</span> as an ordinary email — there is
          nothing to come back to this page for, and nothing here will change when we answer.
        </p>
        <button
          type="button"
          onClick={() => setStatus("idle")}
          className={buttonClass({ variant: "secondary", size: "sm", className: "mt-4" })}
        >
          Send another
        </button>
      </div>
    );
  }

  const sending = status === "sending";
  const remaining = MESSAGE_MAX - message.length;

  return (
    <form onSubmit={submit} className="flex flex-col gap-4">
      <div className="grid gap-4 sm:grid-cols-2">
        <Input
          label="Your name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          autoComplete="name"
          required
          maxLength={120}
          disabled={sending}
        />
        <Input
          label="Reply to"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          autoComplete="email"
          required
          disabled={sending}
          hint="Prefilled from your account. Change it if you want the reply somewhere else."
        />
      </div>

      <Select
        label="Which site is this about?"
        value={siteId}
        onChange={(e) => setSiteId(e.target.value)}
        disabled={sending || sites.length === 0}
        hint={
          sites.length === 0
            ? "You have no sites yet, so there is nothing to attach."
            : "We send the site's name and address along with your message, so nobody has to ask you for them."
        }
      >
        <option value="">Not about one specific site</option>
        {sites.map((site) => (
          <option key={site.id} value={site.id}>
            {site.name}
            {site.published ? "" : " (draft)"}
          </option>
        ))}
      </Select>

      <Textarea
        label="What's going on?"
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        rows={7}
        required
        maxLength={MESSAGE_MAX}
        disabled={sending}
        hint={
          remaining < 400
            ? `${remaining} characters left.`
            : "What you expected, what happened instead, and anything you already tried."
        }
      />

      {error != null && (
        <p
          role="alert"
          className="rounded-md border border-danger/30 bg-danger-tint px-3 py-2.5 text-sm leading-relaxed text-danger"
        >
          {error}
        </p>
      )}

      <div className="flex flex-wrap items-center gap-3">
        <Button
          type="submit"
          variant="primary"
          loading={sending}
          icon={<Send className="size-4" aria-hidden />}
        >
          {sending ? "Sending" : "Send message"}
        </Button>
        <p className="text-xs text-ink-3">
          Or email{" "}
          <a
            href={`mailto:${contactEmail}`}
            className="k-focus rounded-sm underline underline-offset-2"
          >
            {contactEmail}
          </a>{" "}
          — same inbox.
        </p>
      </div>
    </form>
  );
}

